const maxTokenLen = 128 // tokens are 32 random bytes base64url = 43 chars

func (h *DeliveryHandler) HandleConfirmTransfer(c *gin.Context) {
    log := h.deps.Logger()

    token := strings.TrimSpace(c.Param("token"))
    if token == "" || len(token) > maxTokenLen {
        // NOT logged with the token in it. An emailed link is already in
        // access logs, Referer headers and browser history; this process
        // is not going to be a fourth copy.
        log.Info("confirm-transfer refused: malformed token", zap.Int("len", len(token)))
        h.renderConfirm(c, confirmFailed)
        return
    }

    err := h.deps.ConfirmTransfer(c, token)
    switch {
    case err == nil:
        log.Info("transfer confirmed by customer click")
        h.renderConfirm(c, confirmOK)
    case errors.Is(err, delivery.ErrTokenNotFound):
        log.Info("confirm-transfer refused: token not valid")
        h.renderConfirm(c, confirmFailed)
    default:
        log.Error("confirm-transfer failed", zap.Error(err))
        h.renderConfirm(c, confirmError)
    }
}

// renderConfirm writes the page and the headers that keep the token from
// travelling. confirmPage is a html/template with no external reference of
// any kind: no stylesheet, no font, no script, no image.
func (h *DeliveryHandler) renderConfirm(c *gin.Context, outcome confirmOutcome) {
    var v confirmView
    switch outcome {
    case confirmOK:
        v = confirmView{Title: "Thank you, that is recorded.", Paragraphs: []string{
            "We have noted that you have moved everything across. You will not get any more reminders about it.",
            "Your site files are yours to keep, and so is anything you have bought outright."}}
    case confirmFailed:
        v = confirmView{Title: "That link is no longer active.", Paragraphs: []string{
            "It may already have been used, or it may have run out. Either way there is nothing wrong at your end.",
            "If you have already told us you have moved, you do not need to do anything else."}}
    default:
        v = confirmView{Title: "Something went wrong at our end.", Paragraphs: []string{
            "Your link is fine. Please try it again in a few minutes."}}
    }
    c.Status(http.StatusOK)
    c.Header("Content-Type", "text/html; charset=utf-8")
    c.Header("Cache-Control", "no-store")   // the page reflects state THIS request changed
    c.Header("Referrer-Policy", "no-referrer") // the token is in the path
    c.Header("X-Content-Type-Options", "nosniff")
    c.Header("X-Frame-Options", "DENY")
    if err := confirmPage.Execute(c.Writer, v); err != nil {
        h.deps.Logger().Error("confirm page render failed", zap.Error(err))
    }
}

type DeliveryDeps interface {
    ConfirmTransfer(c *gin.Context, token string) error
    Logger() *zap.Logger
}

type dbDeliveryDeps struct {
    db     *sql.DB
    logger *zap.Logger
    now    func() time.Time // swapped by tests; expiry is a boundary
}

func NewDBDeliveryDeps(db *sql.DB, logger *zap.Logger) DeliveryDeps {
    return &dbDeliveryDeps{db: db, logger: logger, now: time.Now}
}

func (d *dbDeliveryDeps) ConfirmTransfer(c *gin.Context, token string) error {
    _, err := delivery.ConfirmTransfer(c.Request.Context(), d.db, token, d.now())
    return err // site id dropped on purpose: the page must not vary by site
}

func (d *dbDeliveryDeps) Logger() *zap.Logger { return d.logger }

siteFactsHandler := handlers.NewSiteFactsHandler(personaRepoImpl.ClientsDB(), s.logger)
s.router.GET("/api/v1/site-facts/:domain", siteFactsHandler.HandleGetSiteFacts)

// Customer handover links (NO authentication, bypasses AuthMiddleware --
// the token in the path IS the credential, hashed at rest, expiring, and
// scoped to one site and one purpose; see platform/delivery).
//
// PUBLICLY REACHABLE, unlike everything else in this service. Customer
// traffic arrives at the webdesign.uk box, whose nginx proxies these NAMED
// PATHS to this service over WireGuard (the /stripe/webhook -> auth-service
// shape). The exposure is exactly the paths nginx names: keep the nginx
// locations exact or tightly prefixed, never a catch-all, or the site-facts
// relay's "ClusterIP only, no ingress" reasoning three lines up silently
// stops being true.
//
// Mounted at the ROOT, not under /api/v1, on purpose: these go in an email
// to a customer and get read aloud and retyped, so the path is two
// characters. There is no /d/<token> yet -- presigning needs object-store
// credentials that no standing service holds by owner directive
// (bugs_open/245); see handlers/delivery.go.
deliveryHandler := handlers.NewDeliveryHandler(
    handlers.NewDBDeliveryDeps(personaRepoImpl.ClientsDB(), s.logger))
s.router.GET("/c/:token", deliveryHandler.HandleConfirmTransfer)

// Cases, and the mutation each one was proved against:
//  1 SucceedsAndSaysSo                 -- also pins that the token reaches the
//    dependency VERBATIM: a handler that trimmed or lower-cased it would hash to
//    a different value and every real link would fail, which no page-copy test sees.
//  2 NeverSaysWHICHFailure             mut: failure page names the reason -> FAIL
//  3 DistinguishesOurFaultFromTheirLink mut: db error -> confirmFailed      -> FAIL
//  4 RefusesAnOversizedToken...        mut: length guard removed            -> FAIL
//  5 DoesNotEchoTheTokenOrLeakItOnward mut: Referrer-Policy removed         -> FAIL
//  6 IsSelfContainedAndObeysVoiceRules mut: an em dash in the copy          -> FAIL

func TestConfirmTransferNeverSaysWHICHFailure(t *testing.T) {
    f := &fakeDeliveryDeps{err: delivery.ErrTokenNotFound}
    w := serve(t, f, http.MethodGet, "/c/abc123")
    if w.Code != http.StatusOK {
        t.Fatalf("status = %d, want 200 (a 404 from a link we emailed reads as a lost site)", w.Code)
    }
    body := strings.ToLower(w.Body.String())
    if !strings.Contains(body, "no longer active") {
        t.Errorf("failure page missing its copy: %q", body)
    }
    for _, leak := range []string{"expired", "revoked", "already been used by",
        "unknown", "not found", "purpose", "site"} {
        if strings.Contains(body, leak) {
            t.Errorf("failure page names a specific failure mode (%q), making it an oracle", leak)
        }
    }
}

func TestConfirmTransferRefusesAnOversizedTokenBeforeTheDatabase(t *testing.T) {
    f := &fakeDeliveryDeps{} // succeeds on ANY token -- that is the point
    w := serve(t, f, http.MethodGet, "/c/"+strings.Repeat("A", maxTokenLen+1))
    if strings.Contains(w.Body.String(), "that is recorded") {
        t.Fatalf("an oversized token was confirmed; the length guard does nothing")
    }
    if len(f.gotTokens) != 0 { t.Errorf("oversized token reached the dependency") }
    f2 := &fakeDeliveryDeps{}
    w2 := serve(t, f2, http.MethodGet, "/c/"+strings.Repeat("A", maxTokenLen))
    if !strings.Contains(w2.Body.String(), "that is recorded") {
        t.Errorf("a token at exactly maxTokenLen was refused; the guard is off by one")
    }
}

